{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "mode",
      "type": "'dark' | 'light' | 'auto' | 'off'",
      "required": true,
      "description": "Surface luminance context: dark for content over dark backgrounds (light text, white-tinted interactions), light for content over light backgrounds (dark text, black-tinted interactions), auto to decide from the painted surface (no media context when the ambient text already reads on the surface at 3:1, otherwise the side that reads better), and off to turn it off explicitly. The element renders either way, so a surface can switch contexts without remounting children."
    },
    {
      "name": "fallback",
      "type": "'dark' | 'light'",
      "default": "'dark'",
      "description": "Which side auto uses when the surface cannot be measured: during SSR, on the first client frame, and whenever the backdrop is not knowable from CSS, most often a background-image, whose pixels need sampling (useImageMode) rather than a computed style. Ignored unless mode is auto."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "required": true,
      "description": "Content to render with inverted token context. Components inherit the correct colors automatically."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
